// Extract query from incoming request
const raw = $input.first().json;
const body = raw.body || raw;
const query = (body.query || body.question || '').toString().trim();

if (!query || query.length < 2) {
  throw new Error('VALIDATION_ERROR: query is required (min 2 chars)');
}

return [{
  json: {
    query: query,
    trace_id: body.trace_id || 'orch-' + Date.now(),
    tenant_id: body.tenant_id || 'default',
    user_context: body.user_context || { tenant_id: body.tenant_id || 'default', groups: ['default'] },
    timestamp: Date.now()
  }
}];

