// Parse LLM response and extract intent
const input = $input.first().json;
const prevData = $node['Parse Input'].json;

// Extract the classification from Groq response
let rawIntent = '';
try {
  rawIntent = (input.choices?.[0]?.message?.content || '').trim().toUpperCase();
} catch(e) {
  rawIntent = 'STANDARD';
}

// Normalize: accept partial matches
let intent = 'STANDARD'; // default fallback
if (rawIntent.includes('GRAPH')) {
  intent = 'GRAPH';
} else if (rawIntent.includes('QUANT')) {
  intent = 'QUANTITATIVE';
} else if (rawIntent.includes('STANDARD')) {
  intent = 'STANDARD';
}

return [{
  json: {
    intent: intent,
    raw_intent: rawIntent,
    query: prevData.query,
    trace_id: prevData.trace_id,
    tenant_id: prevData.tenant_id,
    user_context: prevData.user_context,
    // Build the pipeline request body
    pipeline_body: JSON.stringify({
      query: prevData.query,
      trace_id: prevData.trace_id,
      tenant_id: prevData.tenant_id,
      user_context: JSON.stringify(prevData.user_context || {}),
      topK: 20
    })
  }
}];

// Format the pipeline response for output
const raw = $input.first().json;
const intentData = $node['Parse Intent'].json;

// The pipeline response is the direct HTTP response
let answer = '';
let sources = [];
let confidence = 0;
let pipeline = intentData.intent;
let error = null;

try {
  // Pipeline responses vary in format — handle all cases
  if (raw.error || raw.statusCode >= 400) {
    error = raw.error || raw.message || `Pipeline ${pipeline} returned error`;
    answer = `Error from ${pipeline} pipeline: ${error}`;
    confidence = 0;
  } else {
    // Extract answer from various response formats
    answer = raw.final_response || raw.response || raw.answer || 
             raw.interpretation || raw.chat_message || raw.result || '';

    // If response is nested in body
    if (!answer && raw.body) {
      const body = typeof raw.body === 'string' ? JSON.parse(raw.body) : raw.body;
      answer = body.final_response || body.response || body.answer || '';
    }

    sources = raw.sources || raw.context_sources || [];
    confidence = raw.confidence || raw.score || 0.5;
  }
} catch(e) {
  answer = JSON.stringify(raw).substring(0, 2000);
  confidence = 0.3;
}

// Fallback if still empty
if (!answer || answer.length < 5) {
  answer = 'The pipeline returned an empty response. Please try rephrasing your question.';
  confidence = 0.1;
}

return [{
  json: {
    query: intentData.query,
    intent: pipeline,
    answer: answer,
    sources: Array.isArray(sources) ? sources.slice(0, 10) : [],
    confidence: confidence,
    trace_id: intentData.trace_id,
    pipeline_used: pipeline.toLowerCase(),
    error: error,
    timestamp: new Date().toISOString()
  }
}];
